update public.lessons set content='{"intro": "Nesta aula vai aprender «Urbanismo, ordenamento e gestão territorial» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "O conceito central", "body": "«Urbanismo, ordenamento e gestão territorial» deve ser entendido no contexto do módulo «Fundamentos de Urbanismo e Ordenamento». Antes de agir, identifique o objetivo, os intervenientes, a informação de que dispõe e a informação que ainda falta."}, {"title": "Como se aplica", "body": "Transforme o tema numa sequência observável: recolher → confirmar fonte → comparar → identificar risco/divergência → comunicar → encaminhar quando necessário."}, {"title": "O que nunca assumir", "body": "A declaração de um cliente, uma fotografia, um anúncio antigo ou um único documento não substituem a verificação adequada quando a matéria é relevante para o negócio."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Urbanismo, ordenamento e gestão territorial», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Urbanismo, ordenamento e gestão territorial» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/1999-34567875-45232875', verified_at=date '2026-08-20' where id=78;
update public.lessons set content='{"intro": "Nesta aula vai aprender «RJIGT, RJUE e regulamentos municipais» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "RJUE — RJUE significa Regime Jurídico da Urbanização e da Edificação, regime central dos procedimentos e operações urbanísticas.\n\nRJIGT — RJIGT significa Regime Jurídico dos Instrumentos de Gestão Territorial, que enquadra os instrumentos territoriais como planos e programas."}, {"title": "O conceito central", "body": "«RJIGT, RJUE e regulamentos municipais» deve ser entendido no contexto do módulo «Fundamentos de Urbanismo e Ordenamento». Antes de agir, identifique o objetivo, os intervenientes, a informação de que dispõe e a informação que ainda falta."}, {"title": "Como se aplica", "body": "Transforme o tema numa sequência observável: recolher → confirmar fonte → comparar → identificar risco/divergência → comunicar → encaminhar quando necessário."}, {"title": "O que nunca assumir", "body": "A declaração de um cliente, uma fotografia, um anúncio antigo ou um único documento não substituem a verificação adequada quando a matéria é relevante para o negócio."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «RJIGT, RJUE e regulamentos municipais», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «RJIGT, RJUE e regulamentos municipais» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/1999-34567875-45232875', verified_at=date '2026-08-20' where id=79;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Onde consultar informação oficial» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "O conceito central", "body": "«Onde consultar informação oficial» deve ser entendido no contexto do módulo «Fundamentos de Urbanismo e Ordenamento». Antes de agir, identifique o objetivo, os intervenientes, a informação de que dispõe e a informação que ainda falta."}, {"title": "Como se aplica", "body": "Transforme o tema numa sequência observável: recolher → confirmar fonte → comparar → identificar risco/divergência → comunicar → encaminhar quando necessário."}, {"title": "O que nunca assumir", "body": "A declaração de um cliente, uma fotografia, um anúncio antigo ou um único documento não substituem a verificação adequada quando a matéria é relevante para o negócio."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Onde consultar informação oficial», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Onde consultar informação oficial» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/1999-34567875-45232875', verified_at=date '2026-08-20' where id=80;
update public.lessons set content='{"intro": "Nesta aula vai aprender «Solo urbano e solo rústico» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "O que é o PDM", "body": "PDM significa Plano Diretor Municipal: instrumento territorial municipal que contém regras de organização e uso do território. Deve ser lido através das plantas e do regulamento aplicável."}, {"title": "Planta de ordenamento", "body": "Localiza e enquadra o solo/categoria segundo o plano."}, {"title": "Planta de condicionantes", "body": "Mostra condicionamentos/servidões relevantes que se sobrepõem ao ordenamento."}, {"title": "Regulamento", "body": "Contém regras, usos e parâmetros. Uma cor no mapa não basta: é preciso ler a norma correspondente."}, {"title": "Solo urbano/rústico", "body": "São categorias de classificação territorial; nenhuma delas, isoladamente, responde a toda a edificabilidade."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Solo urbano e solo rústico», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Solo urbano e solo rústico» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/1999-34567875-45232875', verified_at=date '2026-08-20' where id=81;
