update public.lessons set content='{"intro": "Nesta aula vai aprender «Modelos e elementos instrutórios de 2026» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "O conceito central", "body": "«Modelos e elementos instrutórios de 2026» deve ser entendido no contexto do módulo «Operações Urbanísticas e Procedimentos». Antes de agir, identifique o objetivo, os intervenientes, a informação de que dispõe e a informação que ainda falta."}, {"title": "Como se aplica", "body": "Transforme o tema numa sequência observável: recolher → confirmar fonte → comparar → identificar risco/divergência → comunicar → encaminhar quando necessário."}, {"title": "O que nunca assumir", "body": "A declaração de um cliente, uma fotografia, um anúncio antigo ou um único documento não substituem a verificação adequada quando a matéria é relevante para o negócio."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Modelos e elementos instrutórios de 2026», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Modelos e elementos instrutórios de 2026» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/1999-34567875-45232875', verified_at=date '2026-08-20' where id=86;
update public.lessons set content='{"intro": "Nesta aula vai aprender «PIP do artigo 14.º» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "Termos desta aula", "body": "PIP — PIP significa Pedido de Informação Prévia: procedimento urbanístico através do qual se pede à entidade competente uma decisão/informação prévia sobre determinada operação urbanística, nos termos legais aplicáveis."}, {"title": "O que é o PIP", "body": "PIP significa Pedido de Informação Prévia: procedimento urbanístico através do qual se pede à entidade competente uma decisão/informação prévia sobre determinada operação urbanística, nos termos legais aplicáveis."}, {"title": "O que se pede", "body": "A pergunta submetida deve corresponder à operação que se quer esclarecer; um PIP só responde ao que foi efetivamente apreciado."}, {"title": "Como ler uma decisão", "body": "Identificar prédio, pedido, peças, decisão, condicionantes, entidades consultadas e efeitos/prazos aplicáveis."}, {"title": "O que não é", "body": "Não é sinónimo de licença de construção nem autorização para qualquer projeto diferente do apreciado."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «PIP do artigo 14.º», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «PIP do artigo 14.º» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/1999-34567875-45232875', verified_at=date '2026-08-20' where id=87;
