update public.lessons set content='{"intro": "Nesta aula vai aprender «Alteração de uso sem obra prévia» desde a base. Nenhum termo técnico é assumido como conhecido: primeiro é explicado, depois aplicado. O objetivo é que consiga reconhecer o conceito no trabalho real, explicar o que significa e saber qual é o passo seguinte.", "sections": [{"title": "O conceito central", "body": "«Alteração de uso sem obra prévia» deve ser entendido no contexto do módulo «Utilização e Alteração de Uso». Antes de agir, identifique o objetivo, os intervenientes, a informação de que dispõe e a informação que ainda falta."}, {"title": "Como se aplica", "body": "Transforme o tema numa sequência observável: recolher → confirmar fonte → comparar → identificar risco/divergência → comunicar → encaminhar quando necessário."}, {"title": "O que nunca assumir", "body": "A declaração de um cliente, uma fotografia, um anúncio antigo ou um único documento não substituem a verificação adequada quando a matéria é relevante para o negócio."}, {"title": "Exemplo profissional", "body": "Perante uma situação relacionada com «Alteração de uso sem obra prévia», o consultor deve conseguir explicar ao cliente o que sabe, qual a fonte, o que ainda está por confirmar e qual o próximo passo — sem transformar uma hipótese numa certeza."}, {"title": "Limite profissional", "body": "O consultor deve reconhecer a fronteira entre acompanhamento imobiliário e aconselhamento jurídico, fiscal, técnico, financeiro ou urbanístico especializado. Quando a conclusão depende dessa competência, deve encaminhar."}], "takeaway": "No final desta aula deve conseguir explicar «Alteração de uso sem obra prévia» sem depender de siglas ou frases decoradas e aplicá-lo num caso simples de trabalho."}'::jsonb, source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/1999-34567875-45232875', verified_at=date '2026-08-20' where id=100;
